        // Homepage Hero
        "hero.title": "AI가 만든 나의 인생 한 줄",
        "hero.subtitle": "AI가 생성한 한 문장으로 당신의 인생을 발견하세요",
        "hero.description": "생년월일을 입력하고 AI 알고리즘이 밝혀주는 당신만의 인생 통찰을 확인하세요. 친구들과 공유하고 결과를 비교해보세요!",
        "hero.stats": "전 세계 1,000,000개 이상의 문장이 생성되었습니다",

        // Form
        "form.birthdate": "생년월일",
        "form.year": "년",
        "form.month": "월",
        "form.day": "일",
        "form.gender": "성별 (선택사항)",
        "form.gender.prefer_not": "선택 안 함",
        "form.gender.male": "남성",
        "form.gender.female": "여성",
        "form.gender.other": "기타",
        "form.submit": "내 인생 한 줄 보기",
        "form.terms": "이 서비스를 이용하면 다음에 동의하는 것입니다:",
        "form.terms_link": "이용약관",
        "form.and": "및",
        "form.privacy_link": "개인정보처리방침",
        "form.entertainment": "이 서비스는 엔터테인먼트 목적으로만 제공됩니다.",

        // Example Section
        "examples.title": "최근 생성된",
        "examples.title_highlight": "인생 요약",
        "examples.description": "다른 사람들이 발견한 자신만의 인생 문장을 확인해보세요. 모든 문장은 생년월일 분석을 기반으로 고유하게 생성됩니다.",
        "examples.born_in": "탄생월:",
        "examples.quote1": "\"당신은 평범한 순간에서 아름다움을 발견하고, 도전을 성장의 디딤돌로 바꾸는 사람입니다.\"",
        "examples.born1": "3월생",
        "examples.quote2": "\"당신의 여정은 조용한 회복력으로 빛나며, 다른 사람들이 놓치는 것을 이해하는 데서 진정한 강점이 드러납니다.\"",
        "examples.born2": "9월생",
        "examples.quote3": "\"당신은 창의적인 직관으로 삶을 항해하며, 상상을 현실로 바꾸고 주변 사람들에게 영감을 줍니다.\"",
        "examples.born3": "7월생",
        "examples.quote4": "\"진정성을 받아들일 때 강인함이 자연스럽게 따라오며, 당신은 연민으로 이끄는 운명을 가졌습니다.\"",
        "examples.born4": "12월생",
        "examples.quote5": "\"삶에서 당신은 모든 경험에서 더 깊은 의미를 찾고, 지혜가 자연스럽게 결정을 이끕니다.\"",
        "examples.born5": "2월생",
        "examples.quote6": "\"당신은 거리를 넘어 마음을 연결하며 목적을 찾고, 공감이 앞으로 나아가는 길을 안내합니다.\"",
        "examples.born6": "5월생",

        // How It Works
        "how.title": "",
        "how.title_highlight": "AI 인생 한 줄",
        "how.title_end": "은 어떻게 작동하나요?",
