        // Science Section
        "science.title": "당신의 요약 뒤에 숨겨진 과학",
        "science.p1": "AI 인생 한 줄 시스템은 생년월일에서 파생된 숫자 패턴을 분석하는 독자적인 알고리즘을 활용합니다. 이 컴퓨터 접근 방식은 다양한 성격 프레임워크와 심리학 연구에서 영감을 받아, 의미 있고 공감할 수 있는 인생 요약을 생성하는 독특한 분석을 만들어냅니다.",
        "science.p2": "우리의 데이터베이스에는 회복력, 창의성, 공감, 지혜, 모험 등 20개의 다른 성격 카테고리에 걸쳐 800개 이상의 신중하게 작성된 문장 구성 요소가 포함되어 있습니다. 각 구성 요소는 인간의 성격과 인생 경험의 뉘앙스를 이해하는 콘텐츠 전문가들에 의해 개발되었습니다.",
        "science.p3": "생년월일을 입력하면, 알고리즘은 고유한 해시 값을 생성하여 어떤 특성, 맥락, 템플릿의 조합이 당신의 개인 인생 요약을 형성할지 결정합니다. 이것은 각 결과가 결정론적(같은 생년월일은 항상 같은 결과를 생성)이면서도 개인화와 관련성의 느낌을 유지하도록 보장합니다.",
        "science.p4": "이 서비스는 주로 엔터테인먼트 목적으로 제공되지만, 많은 사용자들이 결과에서 진정한 통찰과 성찰을 찾습니다. 잘 구성된 인생 요약의 힘은 예측 정확성에 있지 않고, 자기 성찰과 다른 사람들과의 의미 있는 대화를 촉발하는 능력에 있습니다.",

