        "archive.understanding.highlight": "인생 요약",
        "archive.understanding.title_end": " 이해하기",
        "archive.understanding.p1": "AI 인생 한 줄 아카이브에는 독자적인 알고리즘으로 생성된 수천 개의 고유한 문장이 포함되어 있습니다. 각 문장은 생년월일에 내재된 숫자 패턴을 기반으로 만들어지며, 성격 심리학, 인생 지혜, 영감을 주는 메시지의 요소를 결합합니다.",
        "archive.understanding.p2": "아카이브를 탐색할 때, 다른 출생 기간의 문장이 주제적 유사성을 공유하면서도 고유하게 유지된다는 것을 알 수 있습니다. 이는 시간적 패턴을 기반으로 특정 성격 특성과 인생 테마를 그룹화하면서도 각 개인의 완전한 생년월일이 독특한 결과를 생성하도록 보장하는 알고리즘의 접근 방식을 반영합니다.",
        "archive.understanding.p3": "아카이브는 여러 목적을 제공합니다: 사용자가 문장 데이터베이스의 범위와 깊이를 탐색할 수 있게 하고, 자기 성찰을 위한 영감을 제공하며, 다른 출생 기간 간의 비교를 가능하게 합니다. 많은 사용자들이 가족, 친구, 파트너의 성격과 인생 여정에 대한 통찰을 얻기 위해 문장을 탐색하는 것을 즐깁니다.",
        "archive.understanding.p4": "우리는 새로운 문장과 통찰로 아카이브를 지속적으로 확장합니다. 콘텐츠 팀은 문장 구성 요소가 의미 있고, 긍정적이며, 생각을 자극하는 상태를 유지하도록 정기적으로 검토하고 개선합니다. 엔터테인먼트를 위해서든 진정한 자기 발견을 위해서든, 이러한 AI 생성 인생 요약을 탐색하면서 가치를 찾으시길 바랍니다.",
