        // About Page
        "about.title": "AI Life Summary 소개",
        "about.subtitle": "사람들이 자신을 더 잘 이해할 수 있도록 돕는 기술의 이야기를 발견하세요",
        "about.what.title": "우리가 하는 일",
        "about.what.p1": "AI Life Summary는 생년월일을 기반으로 개인화된 인생 인사이트를 생성하는 독특한 웹 애플리케이션입니다. 수년간의 연구를 통해 개발하고 개선한 정교한 알고리즘을 사용하여 당신이 누구인지, 어떤 여정을 걷고 있는지의 본질을 담은 의미 있고 생각을 자극하는 문장을 만들어냅니다.",
        "about.what.p2": "우리 서비스는 자기 발견과 성격 분석에 대한 시대를 초월한 인간의 관심과 현대 컴퓨팅 기술을 결합합니다. 전통적인 성격 평가가 긴 설문지를 필요로 하는 반면, AI Life Summary는 전 세계 사용자에게 공감을 얻는 간단하고 즉각적이며 공유하기 쉬운 형식으로 경험을 응축합니다.",
        "about.what.p3": "매일 전 세계 수천 명의 사람들이 자신만의 인생 요약을 발견하기 위해 우리 플랫폼을 방문합니다. 개인적인 성찰, 대화의 시작점, 또는 단순한 엔터테인먼트로 사용되든, 우리가 생성한 문장은 그 관련성과 깊이로 사용자들을 지속적으로 놀라게 합니다.",
        "about.mission.title": "우리의 미션",
        "about.mission.p1": "AI Life Summary의 핵심에는 단순하지만 강력한 미션이 있습니다: 사람들이 잠시 멈추고, 성찰하고, 의미 있는 방식으로 자신과 타인과 연결되도록 돕는 것입니다. 빠르게 변화하는 디지털 세상에서 진정한 자기 성찰의 순간은 점점 드물어지고 있습니다. 우리는 잘 만들어진 하나의 문장이 우리가 누구이고 무엇을 소중히 여기는지에 대한 더 깊은 사고의 촉매제가 될 수 있다고 믿습니다.",
        "about.mission.p2": "개인적인 성찰을 넘어, 우리는 사람들 사이의 연결을 촉진하고자 합니다. 친구, 가족, 동료들이 자신의 인생 요약을 공유하고 비교할 때, 대화는 자연스럽게 깊어집니다. 이러한 공유된 경험은 일상적인 상호작용에서는 나타나지 않을 수 있는 유대감과 이해를 만들어냅니다.",
        "about.mission.p3": "우리는 생성된 모든 콘텐츠에서 긍정적이고 고무적인 톤을 유지하기 위해 최선을 다하고 있습니다. 데이터베이스의 모든 문장은 강점을 강조하고, 도전을 건설적으로 인정하며, 성장을 고취하도록 신중하게 작성되었습니다. 우리는 모든 사람이 독특한 재능을 가지고 있으며 우리 플랫폼이 인간 정신을 축소하기보다 축하해야 한다고 믿습니다.",
        "about.how.title": "기술 작동 방식",
        "about.how.p1": "우리 알고리즘은 생년월일에 성격 인사이트로 수학적으로 변환될 수 있는 고유한 숫자 패턴이 포함되어 있다는 원칙에 따라 작동합니다. 생년월일을 입력하면 시스템은 해시 값(생년월일의 숫자 지문)을 생성하고, 이는 개인 인생 요약을 구성하는 데 사용되는 특성, 맥락 및 템플릿의 특정 조합을 결정합니다.",
        "about.how.p2": "문장 생성 시스템은 20개의 성격 카테고리에 걸쳐 800개 이상의 신중하게 작성된 구성 요소로 이루어진 데이터베이스에서 가져옵니다. 이러한 카테고리에는 회복력, 창의성, 공감, 지혜, 모험, 리더십, 연결, 진정성, 성장, 직관 등이 포함됩니다. 각 구성 요소는 뉘앙스, 긍정성, 보편적 관련성에 주의를 기울여 콘텐츠 팀이 작성했습니다.",
        "about.how.p3": "우리 접근 방식을 독특하게 만드는 것은 알고리즘의 결정론적 특성입니다. 같은 생년월일은 항상 같은 결과를 생성하여 사용자가 감사하는 영속성과 진정성을 만들어냅니다. 무작위 생성기와 달리, 우리 시스템은 생년월일과 요약 사이에 진정한 연결을 만들어 결과가 개인적으로 의미있게 느껴지도록 합니다.",
        "about.how.p4": "우리는 사용자 피드백과 지속적인 연구를 바탕으로 알고리즘을 지속적으로 개선하고 문장 데이터베이스를 확장합니다. 우리 팀은 품질, 관련성, 긍정적 영향을 보장하기 위해 생성된 콘텐츠를 정기적으로 검토합니다. 지속적인 개선에 대한 이러한 헌신은 AI Life Summary가 신규 및 재방문 사용자 모두에게 신선하고 가치 있게 유지되도록 합니다.",
        "about.note.title": "서비스에 대한 안내",
        "about.note.p1": "AI Life Summary는 주로 엔터테인먼트와 개인적 성찰을 위해 설계되었습니다. 많은 사용자가 결과에서 진정한 인사이트를 발견하지만, 우리 알고리즘이 과학적 성격 평가 방법이나 예측 분석에 기반하지 않는다는 점을 투명하게 알려드립니다.",
        "about.note.p2": "우리 서비스의 힘은 심리적 정확성에 대한 주장이 아니라 의미 있는 자기 성찰과 대화를 촉진하는 능력에 있습니다. 알고리즘으로 생성되었더라도 잘 만들어진 문장은 우리가 의식적으로 고려하지 않았을 수 있는 자신의 측면을 반영하는 거울 역할을 할 수 있습니다.",
        "about.note.p3": "우리는 사용자가 열린 마음으로 결과에 접근하여 공감되는 것은 받아들이고 그렇지 않은 것은 놓아주기를 권장합니다. AI Life Summary의 가장 좋은 활용법은 당신이 누구인지에 대한 확정적인 진술이 아니라 성찰의 시작점으로 사용하는 것입니다.",
        "about.faq.title": "자주 묻는 질문",
        "about.faq.q1": "내 데이터가 저장되거나 공유되나요?",
        "about.faq.a1": "아니요. 생년월일은 클라이언트 측 알고리즘을 사용하여 브라우저에서 전적으로 처리됩니다. 우리는 개인정보를 전송, 저장 또는 공유하지 않습니다. 개인정보는 완전히 보호됩니다.",
        "about.faq.q2": "왜 매번 같은 결과가 나오나요?",
        "about.faq.a2": "우리 알고리즘은 결정론적입니다. 즉, 같은 입력은 항상 같은 출력을 생성합니다. 이것은 의도적인 것입니다 - 생년월일과 요약 사이에 진정한 연결을 만들어 더 개인적이고 진정성 있게 느껴지게 합니다.",
        "about.faq.q3": "결과를 상업적으로 사용할 수 있나요?",
        "about.faq.a3": "소셜 미디어에서의 개인적 공유는 권장되고 환영됩니다. 상업적 사용의 경우 라이선스 옵션을 논의하기 위해 문의해 주세요.",
        "about.faq.q4": "결과는 얼마나 정확한가요?",
        "about.faq.a4": "AI Life Summary는 과학적 정확성이 아닌 엔터테인먼트와 성찰을 위해 설계되었습니다. 많은 사용자가 결과가 놀랍도록 관련성이 있다고 느끼지만, 공감되는 것을 받아들이고 기대 없이 경험을 즐기시기를 권장합니다.",
        "about.faq.q5": "모바일 앱이 있나요?",
        "about.faq.a5": "우리 웹사이트는 완전히 반응형이며 모바일 기기에서 아름답게 작동합니다. 현재 전용 앱은 없지만, 앱과 같은 경험을 위해 홈 화면에 사이트를 추가할 수 있습니다.",
        "about.faq.q6": "피드백을 어떻게 제공할 수 있나요?",
        "about.faq.a6": "사용자의 의견을 듣는 것을 좋아합니다! AI Life Summary에 대한 생각, 제안 또는 경험을 공유하려면 문의 페이지를 방문해 주세요.",
        "about.cta.title": "당신의 요약을 발견할 준비가 되셨나요?",
        "about.cta.desc": "자신에 대한 의미 있는 인사이트를 발견하세요.",
        "about.cta.btn": "내 인생 요약 보기",

