        // About Page
        "about.title": "关于 AI Life Summary",
        "about.subtitle": "发现帮助人们更好地了解自己的技术背后的故事",
        "about.what.title": "我们的工作",
        "about.what.p1": "AI Life Summary 是一款独特的网络应用程序，可根据您的生日生成个性化的人生洞察。使用我们多年研究开发和完善的复杂算法，我们创造有意义的、发人深省的句子，捕捉您是谁以及您正在走的旅程的本质。",
        "about.what.p2": "我们的服务将人类对自我发现和性格分析的永恒迷恋与现代计算技术相结合。传统的性格评估需要冗长的问卷，而 AI Life Summary 将体验提炼成简单、即时、高度可分享的格式，在全球用户中产生共鸣。",
        "about.what.p3": "每天，来自世界各地的数千人访问我们的平台，发现他们独特的人生总结。无论是用于个人反思、话题开始还是纯粹的娱乐，我们生成的句子始终以其相关性和深度让用户惊喜。",
        "about.mission.title": "我们的使命",
        "about.mission.p1": "AI Life Summary 的核心是一个简单而强大的使命：帮助人们停下来、反思，并以有意义的方式与自己和他人建立联系。在我们快节奏的数字世界中，真正自我反思的时刻变得越来越稀少。我们相信，一句精心设计的话可以成为深入思考我们是谁以及我们重视什么的催化剂。",
        "about.mission.p2": "除了个人反思之外，我们还旨在促进人与人之间的联系。当朋友、家人和同事分享和比较他们的人生总结时，对话自然会加深。这些共享体验创造了日常互动中可能不会出现的纽带和理解。",
        "about.mission.p3": "我们致力于在所有生成的内容中保持积极、鼓舞人心的语调。数据库中的每一句话都经过精心设计，以突出优势、建设性地承认挑战并激励成长。我们相信每个人都有独特的天赋，我们的平台应该庆祝而不是削弱人类精神。",
        "about.how.title": "技术工作原理",
        "about.how.p1": "我们的算法基于这样一个原理运行：生日包含独特的数字模式，可以通过数学转换为性格洞察。当您输入生日时，我们的系统会生成一个哈希值——您生日的数字指纹——然后确定用于构建您个人人生总结的特征、背景和模板的特定组合。",
        "about.how.p2": "句子生成系统从包含 20 个性格类别的 800 多个精心设计的组件的数据库中提取。这些类别包括韧性、创造力、同理心、智慧、冒险、领导力、联系、真实性、成长和直觉等。每个组件都由我们的内容团队编写，注重细微差别、积极性和普遍相关性。",
        "about.how.p3": "使我们的方法独特的是算法的确定性特性。相同的生日总是产生相同的结果，创造出用户所欣赏的永久性和真实性的感觉。与随机生成器不同，我们的系统在您的生日和您的总结之间建立了真正的联系，使结果感觉具有个人意义。",
        "about.how.p4": "我们根据用户反馈和持续研究不断完善算法并扩展句子数据库。我们的团队定期审查生成的内容，以确保质量、相关性和积极影响。这种对持续改进的承诺确保 AI Life Summary 对新用户和回头客都保持新鲜和有价值。",
        "about.note.title": "服务说明",
        "about.note.p1": "AI Life Summary 主要设计用于娱乐和个人反思。虽然许多用户在结果中找到了真正的洞察，但我们想透明地说明，我们的算法并非基于科学的性格评估方法或预测分析。",
        "about.note.p2": "我们服务的力量不在于任何心理准确性的声称，而在于其促进有意义的自我反思和对话的能力。即使是算法生成的句子，一句精心设计的话也可以作为一面镜子，反映我们可能没有有意识考虑过的自己的方面。",
        "about.note.p3": "我们鼓励用户以开放的心态对待结果，接受产生共鸣的部分，放下不产生共鸣的部分。使用 AI Life Summary 的最佳方式是将其作为反思的起点，而不是关于您是谁的最终陈述。",
        "about.faq.title": "常见问题",
        "about.faq.q1": "我的数据会被存储或分享吗？",
        "about.faq.a1": "不会。您的生日完全在您的浏览器中使用我们的客户端算法处理。我们不会传输、存储或分享任何个人信息。您的隐私得到完全保护。",
        "about.faq.q2": "为什么我每次都得到相同的结果？",
        "about.faq.a2": "我们的算法是确定性的，意味着相同的输入总是产生相同的输出。这是有意为之的——它在您的生日和您的总结之间建立了真正的联系，使其感觉更加个人化和真实。",
        "about.faq.q3": "我可以商业使用我的结果吗？",
        "about.faq.a3": "欢迎在社交媒体上进行个人分享。如需商业使用，请联系我们讨论许可选项。",
        "about.faq.q4": "结果有多准确？",
        "about.faq.a4": "AI Life Summary 设计用于娱乐和反思，而非科学准确性。许多用户发现他们的结果出奇地相关，但我们鼓励您接受产生共鸣的部分，享受体验而不抱期望。",
        "about.faq.q5": "有移动应用吗？",
        "about.faq.a5": "我们的网站完全响应式，在移动设备上运行良好。我们目前没有专用应用，但您可以将我们的网站添加到主屏幕以获得类似应用的体验。",
        "about.faq.q6": "如何提供反馈？",
        "about.faq.a6": "我们喜欢听取用户的意见！请访问我们的联系页面分享您对 AI Life Summary 的想法、建议或体验。",
        "about.cta.title": "准备好发现您的总结了吗？",
        "about.cta.desc": "发现关于自己的有意义洞察。",
        "about.cta.btn": "获取我的人生一句话",

