        // Terms of Service
        "terms.title": "服务条款",
        "terms.last_updated": "最后更新：2025年1月",
        "terms.agreement.title": "1. 条款同意",
        "terms.agreement.p1": "欢迎使用AI Life Summary。本服务条款（以下简称「条款」）管辖您对位于ailifesummary.com的AI Life Summary网站（以下简称「网站」）以及AI Life Summary提供的任何相关服务（统称「服务」）的访问和使用。",
        "terms.agreement.p2": "通过访问或使用我们的服务，您同意受本条款的约束。如果您不同意本条款的任何部分，则您无权访问或使用服务。本条款适用于所有希望访问或使用服务的访客、用户和其他人。",
        "terms.agreement.p3": "我们保留随时更新或修改本条款的权利，恕不另行通知。在本条款的任何更改发布后继续使用服务即表示接受这些更改。我们鼓励您定期查阅本条款以了解任何更新。",
        "terms.service.title": "2. 服务描述",
        "terms.service.p1": "AI Life Summary提供一项娱乐服务，根据用户提供的出生日期生成个性化的「人生总结」。我们的服务使用专有算法创建独特的句子，提供有关性格特征和人生主题的见解和反思。",
        "terms.service.p2": "服务按「原样」提供，仅供娱乐和个人反思目的。生成的内容不构成任何形式的专业建议，包括但不限于心理、医疗、财务或法律建议。用户不应依赖服务做出重要的人生决定。",
        "terms.service.p3": "我们不对生成内容的准确性、可靠性或完整性作任何陈述或保证。我们服务产生的结果是算法生成的，应被理解为娱乐而非事实性的性格评估。",
        "terms.eligibility.title": "3. 用户资格",
        "terms.eligibility.p1": "我们的服务面向至少13岁的用户。通过使用服务，您声明并保证您至少13岁。如果您未满18岁，您声明您已获得父母或监护人的同意使用服务。",
        "terms.eligibility.p2": "我们建议所有用户，特别是18岁以下的用户，了解服务仅供娱乐目的。鼓励父母和监护人监督孩子使用服务，并讨论生成内容的娱乐性质。",
        "terms.acceptable.title": "4. 可接受的使用",
        "terms.acceptable.desc": "使用我们的服务时，您同意遵守所有适用的法律法规。您同意不：",
