        "terms.acceptable.item5": "干扰或中断服务或连接到服务的服务器或网络",
        "terms.acceptable.item6": "未经我们事先书面许可，使用任何机器人、蜘蛛、抓取器或其他自动化手段访问服务",
        "terms.acceptable.item7": "绕过、禁用或以其他方式干扰服务的安全相关功能",
        "terms.acceptable.item8": "使用生成的内容骚扰、辱骂、诽谤或伤害他人",
        "terms.acceptable.item9": "将生成内容的性质虚假陈述为科学或专业评估",
        "terms.ip.title": "5. 知识产权",
        "terms.ip.p1": "服务及其原创内容（不包括用户提供的内容）、功能和功能性是并将继续是AI Life Summary及其许可方的专有财产。服务受美国和外国的版权、商标和其他法律保护。",
        "terms.ip.p2": "与服务相关使用的我们的商标、服务标记、图形和徽标是AI Life Summary的商标或注册商标。与服务相关使用的其他商标、服务标记、图形和徽标可能是其各自所有者的商标。",
        "terms.ip.p3": "您被授予有限的许可，可以出于个人非商业目的访问和使用服务。此许可不包括以下权利：修改或复制材料；将材料用于任何商业目的；尝试反编译或逆向工程网站上包含的任何软件；从材料中删除任何版权或其他专有标记；或将材料转让给他人或在任何其他服务器上「镜像」材料。",
        "terms.ip.p4": "用户可以在社交媒体和个人平台上出于非商业目的分享其生成的人生总结。服务或其生成内容的任何商业使用需要AI Life Summary的事先书面许可。",
        "terms.user.title": "6. 用户内容和数据",
        "terms.user.p1": "使用我们的服务时，您提供某些信息，包括您的出生日期和可选的性别。如我们的隐私政策所述，此信息在您的浏览器中本地处理，不会传输到或存储在我们的服务器上。",
        "terms.user.p2": "您保留对您提供的任何个人信息的所有权利。通过提供此信息，您授予我们有限的许可，仅用于在您的浏览器会话中生成个性化人生总结的目的处理此数据。",
        "terms.disclaimers.title": "7. 免责声明",
        "terms.disclaimers.p1": "服务按「原样」和「可用」的基础提供，不提供任何形式的明示或暗示保证，包括但不限于对适销性、特定用途适用性或非侵权的暗示保证。",
        "terms.disclaimers.p2": "我们不保证服务将不间断、及时、安全或无错误。我们不保证使用服务获得的结果将准确或可靠。",
        "terms.disclaimers.p3": "我们服务生成的内容仅供娱乐目的，不应被视为心理评估、医疗建议或任何其他形式的专业建议。您承认对此类内容的任何依赖完全由您自行承担风险。",
        "terms.liability.title": "8. 责任限制",
        "terms.liability.p1": "在任何情况下，AI LIFE SUMMARY、其董事、员工、合作伙伴、代理、供应商或关联公司均不对因您访问或使用或无法访问或使用服务而产生的任何间接、附带、特殊、后果性或惩罚性损害负责，包括但不限于利润、数据、使用、商誉或其他无形损失的损失。",
        "terms.liability.p2": "我们对您因服务引起或与服务相关的所有索赔的总责任不得超过您在索赔前十二（12）个月内为访问服务向我们支付的金额（如有）。",
        "terms.indemnification.title": "9. 赔偿",
        "terms.indemnification.desc": "您同意为AI Life Summary、其关联公司、许可方和服务提供商，及其各自的管理人员、董事、员工、承包商、代理、许可方、供应商、继承人和受让人进行辩护、赔偿并使其免受因您违反本条款或使用服务而引起或与之相关的任何索赔、责任、损害、判决、裁决、损失、成本、费用或收费（包括合理的律师费）的损害。",
        "terms.governing.title": "10. 管辖法律",
        "terms.governing.p1": "本条款应受美国法律管辖并据此解释，不考虑其法律冲突条款。我们未能执行本条款的任何权利或条款不应被视为放弃这些权利。",
        "terms.governing.p2": "如果本条款的任何条款被法院认定为无效或不可执行，本条款的其余条款将继续有效。本条款构成我们之间关于服务的完整协议，并取代我们之间可能就服务达成的任何先前协议。",
        "terms.changes.title": "11. 条款变更",
        "terms.changes.p1": "我们保留自行决定随时修改或替换本条款的权利。如果修订是重大的，我们将在任何新条款生效前至少提前30天通知。什么构成重大变更将由我们自行决定。",
        "terms.changes.p2": "在任何修订生效后继续访问或使用我们的服务，即表示您同意受修订条款的约束。如果您不同意新条款，您将不再被授权使用服务。",
        "terms.termination.title": "12. 终止",
        "terms.termination.desc": "我们可能因任何原因（包括但不限于您违反条款）立即终止或暂停您对服务的访问，恕不另行通知或承担责任。终止后，您使用服务的权利将立即终止。",
        "terms.contact.title": "13. 联系信息",
        "terms.contact.desc": "如果您对本条款有任何问题，请联系我们：",
