        "examples.title": "Resúmenes Generados",
        "examples.title_highlight": "Recientemente",
        "examples.description": "Mira lo que otros han descubierto sobre sí mismos. Cada oración es única y personalizada basada en el análisis de fecha de nacimiento.",
        "examples.born_in": "Nacido en",
        "examples.quote1": "\"Eres alguien que encuentra belleza en momentos ordinarios y transforma los desafíos en peldaños para el crecimiento.\"",
        "examples.born1": "Nacido en Marzo",
        "examples.quote2": "\"Tu viaje está marcado por una resiliencia silenciosa, y tu fuerza radica en comprender lo que otros a menudo pasan por alto.\"",
        "examples.born2": "Nacido en Septiembre",
        "examples.quote3": "\"Navegas la vida con intuición creativa, convirtiendo la imaginación en realidad mientras inspiras a quienes te rodean.\"",
        "examples.born3": "Nacido en Julio",
        "examples.quote4": "\"La fuerza viene naturalmente cuando abrazas la autenticidad, pues estás destinado a liderar con compasión.\"",
        "examples.born4": "Nacido en Diciembre",
        "examples.quote5": "\"En la vida, buscas un significado más profundo en cada experiencia, y la sabiduría fluye naturalmente a través de tus decisiones.\"",
        "examples.born5": "Nacido en Febrero",
        "examples.quote6": "\"Encuentras propósito conectando corazones a través de distancias, y la empatía guía tu camino hacia adelante.\"",
        "examples.born6": "Nacido en Mayo",

        // How It Works
        "how.title": "¿Cómo Funciona",
        "how.title_highlight": "AI Life Summary",
        "how.title_end": "?",
        "how.description": "Nuestro innovador algoritmo combina análisis computacional con percepciones de personalidad para crear resúmenes de vida significativos y personalizados.",
        "how.step1.title": "Ingresa Tu Fecha de Nacimiento",
        "how.step1.desc": "Tu fecha de nacimiento contiene patrones numéricos únicos que nuestro algoritmo utiliza como base para tu análisis personalizado.",
        "how.step2.title": "Análisis de IA",
        "how.step2.desc": "Nuestro sofisticado algoritmo procesa tus datos a través de múltiples matrices de personalidad para identificar tus rasgos centrales y temas de vida.",
        "how.step3.title": "Obtén Tu Resumen",
        "how.step3.desc": "Recibe una oración bellamente elaborada que captura la esencia de quién eres, lista para compartir con amigos y familia.",

        // Science Section
        "science.title": "La Ciencia Detrás de Tu Resumen",
        "science.p1": "El sistema AI Life Summary utiliza un algoritmo propietario que analiza patrones numéricos derivados de tu fecha de nacimiento. Este enfoque computacional se inspira en varios marcos de personalidad e investigación psicológica, creando una mezcla única de análisis que produce resúmenes de vida significativos y relacionables.",
        "science.p2": "Nuestra base de datos contiene más de 800 componentes de oraciones cuidadosamente elaborados en 20 categorías de personalidad diferentes, incluyendo resiliencia, creatividad, empatía, sabiduría y aventura. Cada componente ha sido desarrollado por especialistas en contenido que comprenden los matices de la personalidad humana y las experiencias de vida.",
        "science.p3": "Cuando ingresas tu fecha de nacimiento, nuestro algoritmo genera un valor hash único que determina qué combinación de rasgos, contextos y plantillas formarán tu resumen de vida personal. Esto asegura que cada resultado sea determinista (la misma fecha de nacimiento siempre produce el mismo resultado) mientras mantiene la sensación de personalización y relevancia.",
        "science.p4": "Aunque presentamos este servicio principalmente con fines de entretenimiento, muchos usuarios encuentran percepciones genuinas y reflexión en sus resultados. El poder de un resumen de vida bien elaborado no radica en su precisión predictiva, sino en su capacidad para provocar autorreflexión y conversaciones significativas con otros.",

        // Why Try Section
        "why.title": "¿Por Qué Probar",
        "why.title_highlight": "AI Life Summary",
        "why.title_end": "?",
        "why.discovery.title": "Autodescubrimiento",
        "why.discovery.desc": "A veces una sola oración puede provocar una profunda autorreflexión. Nuestros resúmenes generados por IA a menudo destacan aspectos de tu personalidad que quizás no hayas reconocido conscientemente, ofreciendo una perspectiva fresca sobre quién eres.",
        "why.share.title": "Comparte y Compara",
        "why.share.desc": "Genera resúmenes para tus amigos y familiares. Compara resultados y descubre patrones interesantes entre personas nacidas en períodos similares. Es una forma divertida de iniciar conversaciones significativas.",
        "why.image.title": "Hermosas Imágenes Compartibles",
        "why.image.desc": "Crea imágenes impresionantes de tu resumen de vida para compartir en Instagram, Twitter y otras plataformas sociales. Nuestro generador de imágenes incorporado crea visuales llamativos perfectos para redes sociales.",
        "why.privacy.title": "Privacidad Primero",
        "why.privacy.desc": "Tomamos tu privacidad en serio. Tu fecha de nacimiento se procesa localmente en tu navegador, y no almacenamos ninguna información personal en nuestros servidores. Disfruta la experiencia sin preocupaciones.",

