        "contact.help.feedback": "Compartir Comentarios",
        "contact.help.feedback_desc": "Siempre buscamos mejorar. Cuéntanos qué piensas sobre AI Life Summary y cómo podemos hacerlo mejor.",
        "contact.help.issues": "Reportar Problemas",
        "contact.help.issues_desc": "¿Encontraste un error o problema técnico? Por favor avísanos para que podamos solucionarlo y mejorar la experiencia para todos.",
        "contact.help.partner": "Colabora con Nosotros",
        "contact.help.partner_desc": "¿Interesado en colaborar o asociarte con AI Life Summary? Nos encantaría explorar oportunidades juntos.",

        // About Page
        "about.title": "Acerca de AI Life Summary",
        "about.subtitle": "Descubre la historia detrás de la tecnología que ayuda a las personas a entenderse mejor",
        "about.what.title": "Lo Que Hacemos",
        "about.what.p1": "AI Life Summary es una aplicación web única que genera percepciones de vida personalizadas basadas en tu fecha de nacimiento. Utilizando un sofisticado algoritmo que hemos desarrollado y refinado a lo largo de años de investigación, creamos oraciones significativas y estimulantes que capturan la esencia de quién eres y el viaje que estás recorriendo.",
        "about.what.p2": "Nuestro servicio combina la fascinación humana atemporal por el autodescubrimiento y el análisis de personalidad con técnicas computacionales modernas. Mientras que las evaluaciones de personalidad tradicionales requieren cuestionarios extensos, AI Life Summary destila la experiencia en un formato simple, instantáneo y altamente compartible que resuena con usuarios de todo el mundo.",
        "about.what.p3": "Cada día, miles de personas de todo el mundo visitan nuestra plataforma para descubrir sus resúmenes de vida únicos. Ya sea para reflexión personal, para iniciar conversaciones o simplemente para entretenimiento, nuestras oraciones generadas sorprenden consistentemente a los usuarios con su relevancia y profundidad.",
        "about.mission.title": "Nuestra Misión",
        "about.mission.p1": "En el corazón de AI Life Summary hay una misión simple pero poderosa: ayudar a las personas a detenerse, reflexionar y conectarse consigo mismas y con otros de maneras significativas. En nuestro mundo digital acelerado, los momentos de reflexión genuina se han vuelto cada vez más raros. Creemos que una sola oración bien elaborada puede servir como catalizador para un pensamiento más profundo sobre quiénes somos y qué valoramos.",
        "about.mission.p2": "Más allá de la reflexión individual, nuestro objetivo es fomentar la conexión entre las personas. Cuando amigos, familiares y colegas comparten y comparan sus resúmenes de vida, las conversaciones naturalmente se profundizan. Estas experiencias compartidas crean vínculos y comprensión que de otra manera no surgirían en las interacciones cotidianas.",
        "about.mission.p3": "Estamos comprometidos a mantener un tono positivo y edificante en todo nuestro contenido generado. Cada oración en nuestra base de datos ha sido cuidadosamente elaborada para destacar fortalezas, reconocer desafíos de manera constructiva e inspirar crecimiento. Creemos que todos tienen dones únicos y que nuestra plataforma debe celebrar, no disminuir, el espíritu humano.",
        "about.how.title": "Cómo Funciona Nuestra Tecnología",
        "about.how.p1": "Nuestro algoritmo opera sobre el principio de que las fechas de nacimiento contienen patrones numéricos únicos que pueden transformarse matemáticamente en percepciones de personalidad. Cuando ingresas tu fecha de nacimiento, nuestro sistema genera un valor hash —una huella digital numérica de tu fecha de nacimiento— que luego determina la combinación específica de rasgos, contextos y plantillas utilizadas para construir tu resumen de vida personal.",
        "about.how.p2": "El sistema de generación de oraciones extrae de una base de datos de más de 800 componentes cuidadosamente elaborados en 20 categorías de personalidad. Estas categorías incluyen resiliencia, creatividad, empatía, sabiduría, aventura, liderazgo, conexión, autenticidad, crecimiento e intuición, entre otras. Cada componente ha sido escrito por nuestro equipo de contenido con atención al matiz, la positividad y la relevancia universal.",
        "about.how.p3": "Lo que hace único nuestro enfoque es la naturaleza determinista del algoritmo. La misma fecha de nacimiento siempre producirá el mismo resultado, creando una sensación de permanencia y autenticidad que los usuarios aprecian. A diferencia de los generadores aleatorios, nuestro sistema crea una conexión genuina entre tu fecha de nacimiento y tu resumen, haciendo que el resultado se sienta personalmente significativo.",
        "about.how.p4": "Continuamente refinamos nuestro algoritmo y expandimos nuestra base de datos de oraciones basándonos en los comentarios de los usuarios y la investigación continua. Nuestro equipo revisa regularmente el contenido generado para garantizar calidad, relevancia e impacto positivo. Este compromiso con la mejora continua asegura que AI Life Summary se mantenga fresco y valioso tanto para usuarios nuevos como recurrentes.",
        "about.note.title": "Una Nota Sobre Nuestro Servicio",
        "about.note.p1": "AI Life Summary está diseñado principalmente para entretenimiento y reflexión personal. Si bien muchos usuarios encuentran percepciones genuinas en sus resultados, queremos ser transparentes en que nuestro algoritmo no está basado en métodos científicos de evaluación de personalidad ni en análisis predictivo.",
        "about.note.p2": "El poder de nuestro servicio no radica en ninguna afirmación de precisión psicológica, sino en su capacidad para provocar reflexión significativa y conversación. Una oración bien elaborada, incluso una generada algorítmicamente, puede servir como un espejo que refleja aspectos de nosotros mismos que quizás no hayamos considerado conscientemente.",
        "about.note.p3": "Animamos a los usuarios a abordar sus resultados con mente abierta, tomando lo que resuena y dejando lo que no. El mejor uso de AI Life Summary es como punto de partida para la reflexión, no como una declaración definitiva sobre quién eres.",
        "about.faq.title": "Preguntas Frecuentes",
        "about.faq.q1": "¿Se almacenan o comparten mis datos?",
        "about.faq.a1": "No. Tu fecha de nacimiento se procesa completamente en tu navegador usando nuestro algoritmo del lado del cliente. No transmitimos, almacenamos ni compartimos ninguna información personal. Tu privacidad está completamente protegida.",
        "about.faq.q2": "¿Por qué obtengo el mismo resultado cada vez?",
        "about.faq.a2": "Nuestro algoritmo es determinista, lo que significa que la misma entrada siempre produce la misma salida. Esto es intencional — crea una conexión genuina entre tu fecha de nacimiento y tu resumen, haciéndolo sentir más personal y auténtico.",
        "about.faq.q3": "¿Puedo usar mis resultados comercialmente?",
        "about.faq.a3": "Compartir en redes sociales para uso personal es bienvenido y alentado. Para uso comercial, por favor contáctanos para discutir opciones de licencia.",
        "about.faq.q4": "¿Qué tan precisos son los resultados?",
        "about.faq.a4": "AI Life Summary está diseñado para entretenimiento y reflexión, no para precisión científica. Muchos usuarios encuentran sus resultados sorprendentemente relevantes, pero te animamos a tomar lo que resuena y disfrutar la experiencia sin expectativas.",
        "about.faq.q5": "¿Hay una aplicación móvil disponible?",
        "about.faq.a5": "Nuestro sitio web es completamente responsivo y funciona perfectamente en dispositivos móviles. Actualmente no tenemos una aplicación dedicada, pero puedes agregar nuestro sitio a tu pantalla de inicio para una experiencia similar a una aplicación.",
        "about.faq.q6": "¿Cómo puedo proporcionar comentarios?",
        "about.faq.a6": "¡Nos encanta escuchar a nuestros usuarios! Por favor visita nuestra página de Contacto para compartir tus pensamientos, sugerencias o experiencias con AI Life Summary.",
        "about.cta.title": "¿Listo para Descubrir Tu Resumen?",
        "about.cta.desc": "Descubre percepciones significativas sobre ti mismo.",
        "about.cta.btn": "Obtener Mi Resumen de Vida",

