        // Privacy Policy
        "privacy.title": "Política de Privacidad",
        "privacy.last_updated": "Última actualización: 9 de mayo de 2026",
        "privacy.intro.title": "Introducción",
        "privacy.intro.p1": "Bienvenido a AI Life Summary (\"nosotros\", \"nuestro\" o \"nos\"). Estamos comprometidos a proteger su privacidad y garantizar que tenga una experiencia positiva al usar nuestro sitio web y servicios. Esta Política de Privacidad explica cómo recopilamos, usamos, divulgamos y protegemos su información cuando visita nuestro sitio web en ailifesummary.com (el \"Sitio\") y utiliza nuestro servicio de generación de resumen de vida impulsado por IA (el \"Servicio\").",
        "privacy.intro.p2": "Por favor lea esta Política de Privacidad cuidadosamente. Al acceder o usar nuestro Sitio y Servicio, usted reconoce que ha leído, entendido y acepta estar sujeto a todos los términos de esta Política de Privacidad. Si no está de acuerdo con los términos de esta Política de Privacidad, por favor no acceda ni use nuestro Sitio o Servicio.",
        "privacy.intro.p3": "Nos reservamos el derecho de hacer cambios a esta Política de Privacidad en cualquier momento y por cualquier razón. Le alertaremos sobre cualquier cambio actualizando la fecha de \"Última actualización\" de esta Política de Privacidad. Le animamos a revisar periódicamente esta Política de Privacidad para mantenerse informado de las actualizaciones. Se considerará que ha sido informado, estará sujeto y se considerará que ha aceptado los cambios en cualquier Política de Privacidad revisada por su uso continuado del Sitio y Servicio después de la fecha en que se publique dicha Política de Privacidad revisada.",
        "privacy.collect.title": "Información que Recopilamos",
        "privacy.collect.personal.title": "Información Personal que Usted Proporciona",
        "privacy.collect.personal.desc": "Cuando usa nuestro Servicio, puede proporcionarnos cierta información personal, específicamente:",
        "privacy.collect.personal.dob": "<strong>Fecha de Nacimiento:</strong> Recopilamos su fecha de nacimiento para generar su resumen de vida personalizado. Esta información se utiliza únicamente con el propósito de ejecutar nuestro algoritmo y generar su resultado. Es importante destacar que estos datos se procesan completamente dentro de su navegador web usando JavaScript del lado del cliente y nunca se transmiten a nuestros servidores.",
        "privacy.collect.personal.gender": "<strong>Género (Opcional):</strong> Opcionalmente puede proporcionar su género para recibir un resultado más personalizado. Esta información, como su fecha de nacimiento, se procesa localmente en su navegador y no se transmite ni almacena en nuestros servidores.",
        "privacy.collect.personal.lifestyle": "<strong>Respuestas de Encuesta de Estilo de Vida (Calculadora de Edad AI):</strong> Al usar nuestra Calculadora de Edad AI, responde preguntas sobre su estilo de vida, hábitos y mentalidad. Estas respuestas se procesan completamente en su navegador para calcular su Edad Mental y Edad Energética. Estos datos se almacenan solo en el almacenamiento local de su navegador y nunca se transmiten a nuestros servidores.",
        "privacy.collect.auto.title": "Información Recopilada Automáticamente",
        "privacy.collect.auto.desc": "Cuando accede a nuestro Sitio, cierta información puede recopilarse automáticamente, incluyendo:",
        "privacy.collect.auto.device": "<strong>Información del Dispositivo:</strong> Podemos recopilar información sobre su dispositivo, incluyendo tipo de dispositivo, sistema operativo, identificadores únicos del dispositivo e información de la red móvil.",
        "privacy.collect.auto.browser": "<strong>Información del Navegador:</strong> Podemos recopilar información sobre el tipo de su navegador, versión, preferencias de idioma y configuración.",
